def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.179.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.178.0"' not in init:
        sys.exit("ABORT: not at v3.178.0.")
    for k in ("warehouses", "stock_entries"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("INV1", LESSONS_I1, QUESTIONS_I1, 9) + _validate("INV2", LESSONS_I2, QUESTIONS_I2, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("INV 1", LESSONS_I1, QUESTIONS_I1, "warehouses",
         "The Warehouse master and stock architecture in ZhiftERP: the Warehouse doctype field walk — tree position, Is Group, warehouse types, the account resolution, retirement by the Disabled flag at zero; the three-level tree design with a written naming convention and the three design tests; the transit, quarantine, and subcontract warehouses; the default warehouse resolution chain with the Item Defaults table and the monthly fallback read; the Bin — actual, reserved, ordered, and projected quantities, derived and never edited; and warehouse custody — the keeper list, the role separation, and site scoping."),
        ("INV 2", LESSONS_I2, QUESTIONS_I2, "stock_entries",
         "The Stock Entry and internal movements in ZhiftERP: the purpose walk — Material Transfer, Material Issue, Material Receipt, Repack, Send to Subcontractor; the full field walk including named Stock Entry Types, the rate rules per purpose, and the Difference Account; the issue and receipt lanes with their lawful cases, evidence, and approval ladder; one-step and two-step transfers through the transit warehouse with the shortfall procedure and the transit reads; Repack from the conversion register with the value-conservation rule; the subcontract despatch and vendor stock reconciliation; and the posting discipline — honest dates, backdating controls, the correction lane, and the monthly reads."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.178.0"', '"3.179.0"'))
    print("  data: INVENTORY 1 + 2 lessons + banks REPLACED (style v3, strict manual register)")
    print("wrote __version__ -> 3.179.0")


if __name__ == "__main__":
    main()
